import { action } from "solid-js";
const go = (cb) => { void action(function* () { if (typeof cb === "function") cb(); })(); };
const realAdd = window.addEventListener.bind(window);
window.addEventListener = (type, cb, o) => { if (type === "fz") go(cb); else realAdd(type, cb, o); };
const realST = globalThis.setTimeout;
globalThis.setTimeout = (cb, ms, ...r) => (ms === "fz" ? (go(cb), 0) : realST(cb, ms, ...r));
globalThis.fzGlobal = (cb) => go(cb);
globalThis.fzVoid = () => go();
window.fzHook = () => go();
Reflect.fzRun = (cb) => go(cb);
export const exec = (resolve) => { go(); resolve(1); };
